$_MODULE['<{inpostizi}prestashop>admin_template_translations_df4069cdb9787753503ca5dae66919c0'] = 'Pamiętaj by kliknąć przycisk \'Zapisz\' gdy już skonfigurujesz wygląd przycisku';
